Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
#define int long long
using namespace std;

struct Fraction {
    int num, den;
};

signed main() {
    int x, y, n;
    cin >> x >> y >> n;
    long double best = 1e30;
    Fraction ans = {0, 0};
    for (int i = 1; i <= n; ++i) {
        int a = x * i / y;
        long double d1 = fabs((long double)x / y - (long double)a / i);
        if (d1 < best) {
            best = d1;
            ans = {a, i};
        }
        int a2 = a + 1;
        long double d2 = fabs((long double)x / y - (long double)a2 / i);
        if (d2 < best) {
            best = d2;
            ans = {a2, i};
        }
    }
    cout << ans.num << "/" << ans.den << endl;
    return 0;
}
</original_code>
